CREATE TABLE [dbo].[CRMxTemplates](	  [id] INT NOT NULL IDENTITY(1,1)	, [name] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [description] NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [isActive] BIT NOT NULL DEFAULT((0))	, [displayData] BIT NOT NULL DEFAULT((0))	, [dataSavingModality] NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [dataKeyType] NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [servicesType] NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT(N'none')	, [servicesRelation] XML NOT NULL DEFAULT('<servicesRelation><call/></servicesRelation>')	, [hasSavedData] BIT NOT NULL DEFAULT((0))	, [hasBeenLogicDeleted] BIT NOT NULL DEFAULT((0))	, [isLoadingData] BIT NULL DEFAULT(N'0')	, CONSTRAINT [PK_CRMxTemplates] PRIMARY KEY ([id] ASC))